  font-size: 14px;
}

form {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

label {
  font-weight: 500;
  font-size: 14px;
  color: #2d3748;
  display: flex;
  align-items: center;
  gap: 4px;
}

span[aria-hidden="true"] {
  color: #e53e3e;
  font-weight: 600;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  padding: 12px 14px;
  border: 2px solid #e2e8f0;
  border-radius: 6px;
  font-size: 16px;
  font-family: inherit;
  transition: all 0.2s ease;
  background: white;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
  outline: none;
  border-color: #667eea;
  box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

input[type="text"]:hover,
input[type="email"]:hover,
input[type="tel"]:hover {
  border-color: #cbd5e0;
}

input[aria-invalid="true"] {
  border-color: #e53e3e;
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(229, 62, 62, 0.1);
}

.help-text {
  font-size: 12px;
  color: #718096;
  margin: 0;
}

.error-message {
  font-size: 13px;
  color: #e53e3e;
  margin: 0;
  display: none;
  font-weight: 500;
}

.error-message.show {
  display: block;
}

.submit-button {
  padding: 12px 24px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  border: none;
  border-radius: 6px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  margin-top: 8px;
}

.submit-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 25px rgba(102, 126, 234, 0.3);
}

.submit-button:active {
  transform: translateY(0);
}

.submit-button:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.3);
}

.success-message {
  display: none;
  margin-top: 24px;
  padding: 16px;
  background: #c6f6d5;
  color: #22543d;
  border-radius: 6px;
  border-left: 4px solid #38a169;
  animation: slideIn 0.4s ease-out;
}

.success-message.show {
  display: block;
}

@media (max-width: 480px) {
  .contact-container {
    padding: 24px;
  }

  h1 {
    font-size: 24px;
  }

  form {
    gap: 20px;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}
