**script.js:**

const form = document.getElementById('contactForm');
const fullNameInput = document.getElementById('fullName');
const emailInput = document.getElementById('email');
const phoneInput = document.getElementById('phone');
const successMessage = document.getElementById('successMessage');

// Validation patterns
const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const phonePattern = /^[\d\s\-\(\)]*$/;

// Validate full name
function validateFullName(value) {
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    return { valid: false, message: 'Error: Full name is required.' };
  }
  if (trimmed.length < 2) {
    return { valid: false, message: 'Error: Full name must be at least 2 characters.' };
  }
  return { valid: true, message: '' };
}

// Validate email
function validateEmail(value) {
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    return { valid: false, message: 'Error: Email address is required.' };
  }
  if (!emailPattern.test(trimmed)) {
    return { valid: false, message: 'Error: Enter a valid email like name@example.com.' };
  }
  return { valid: true, message: '' };
}

// Validate phone (optional, but if provided, must be valid format)
function validatePhone(value) {
  if (value.trim().length === 0) {
    return { valid: true, message: '' };
  }
  if (!phonePattern.test(value)) {
    return { valid: false, message: 'Error: Phone number contains invalid characters.' };
  }
  // Basic length check for phone
  const digitsOnly = value.replace(/\D/g, '');
  if (digitsOnly.length > 0 && (digitsOnly.length < 10 || digitsOnly.length > 15)) {
    return { valid: false, message: 'Error: Phone number should be 10-15 digits.' };
  }
  return { valid: true, message: '' };
}

// Update field validation display
function updateFieldValidation(input, errorElement, isValid, message) {
  if (isValid) {
    input.removeAttribute('aria-invalid');
    errorElement.textContent = '';
    errorElement.classList.remove('show');
  } else {
    input.setAttribute('aria-invalid', 'true');
    errorElement.textContent = message;
    errorElement.classList.add('show');
  }
}

// Real-time validation
fullNameInput.addEventListener('blur', () => {
  const result = validateFullName(fullNameInput.value);
  const errorElement = document.getElementById('fullName-error');
  updateFieldValidation(fullNameInput, errorElement, result.valid, result.message);
});

emailInput.addEventListener('blur', () => {
  const result = validateEmail(emailInput.value);
  const errorElement = document.getElementById('email-error');
  updateFieldValidation(emailInput, errorElement, result.valid, result.message);
});

phoneInput.addEventListener('blur', () => {
  const result = validatePhone(phoneInput.value);
  // Phone field doesn't have an error element since it's optional
  // but we can still validate when provided
  if (!result.valid) {
    phoneInput.setAttribute('aria-invalid', 'true');
  } else {
    phoneInput.removeAttribute('aria-invalid');
  }
});

// Handle form submission
form.addEventListener('submit', (e) => {
  e.preventDefault();

  // Validate all fields
  const fullNameResult = validateFullName(fullNameInput.value);
  const emailResult = validateEmail(emailInput.value);
  const phoneResult = validatePhone(phoneInput.value);

  const fullNameError = document.getElementById('fullName-error');
  const emailError = document.getElementById('email-error');

  updateFieldValidation(fullNameInput, fullNameError, fullNameResult.valid, fullNameResult.message);
  updateFieldValidation(emailInput, emailError, emailResult.valid, emailResult.message);

  if (phoneResult.valid) {
    phoneInput.removeAttribute('aria-invalid');
  } else {
    phoneInput.setAttribute('aria-invalid', 'true');
  }

  // If there are validation errors, focus the first invalid field
  if (!fullNameResult.valid) {
    fullNameInput.focus();
    return;
  }
  if (!emailResult.valid) {
    emailInput.focus();
    return;
  }
  if (!phoneResult.valid) {
    phoneInput.focus();
    return;
  }

  // Form is valid, show success message
  successMessage.textContent = 'Thank you! Your message has been sent successfully. We\'ll get back to you within 24 hours.';
  successMessage.classList.add('show');

  // Reset form
  form.reset();

  // Clear any error states
  fullNameError.textContent = '';
  fullNameError.classList.remove('show');
  emailError.textContent = '';
  emailError.classList.remove('show');
  fullNameInput.removeAttribute('aria-invalid');
  emailInput.removeAttribute('aria-invalid');
  phoneInput.removeAttribute('aria-invalid');

  // Hide success message after 5 seconds
  setTimeout(() => {
    successMessage.classList.remove('show');
    successMessage.textContent = '';
  }, 5000);
});

// Clear success message on input
form.addEventListener('input', () => {
  if (successMessage.classList.contains('show')) {
    successMessage.classList.remove('show');
    successMessage.textContent = '';
  }
});

